import{_ as o,o as a,c as i,ae as n}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"ADR-003: Zero-Dependency Hand-Written MCP","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adrs/003.md","filePath":"reference/adrs/003.md"}'),t={name:"reference/adrs/003.md"};function s(r,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-003-zero-dependency-hand-written-mcp" tabindex="-1">ADR-003: Zero-Dependency Hand-Written MCP <a class="header-anchor" href="#adr-003-zero-dependency-hand-written-mcp" aria-label="Permalink to &quot;ADR-003: Zero-Dependency Hand-Written MCP&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>oh-my-codex uses <code>@modelcontextprotocol/sdk</code> for its 5 MCP servers. The SDK provides connection management, protocol validation, type safety, and transport abstractions. However, it adds a runtime dependency with its own dependency tree.</p><p>omm has a single MCP server (state access only) with 3 tools. The MCP 2024-11-05 protocol over stdio is straightforward: one JSON-RPC message per line, a simple handshake, and a small method set (<code>initialize</code>, <code>tools/list</code>, <code>tools/call</code>).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>omm implements MCP manually using only Node.js built-in modules（零依赖手写实现）:</p><ul><li><code>node:readline</code> for line-by-line stdin parsing (CRLF-tolerant)</li><li><code>JSON.parse</code> / <code>JSON.stringify</code> for JSON-RPC message handling</li><li><code>node:fs/promises</code> for state file I/O</li><li>Inline validation logic mirroring <code>omm-state-validation.ts</code></li></ul><p>No external packages are imported at runtime.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Zero runtime dependencies — nothing to audit, update, or break</li><li>Minimal bundle size: the entire MCP server is ~260 lines</li><li>Full control over protocol handling — no SDK abstractions to work around</li><li>Matches omm&#39;s overall zero-dependency design philosophy</li></ul><p><strong>Negative:</strong></p><ul><li>Manual protocol tracking: if MCP spec evolves past 2024-11-05, omm must update manually</li><li>Duplicated validation: MCP server inlines a simplified copy of plugin validation logic, creating a maintenance surface for keeping them in sync</li><li>No type-safe protocol layer: JSON-RPC parsing uses <code>as</code> casts, not validated schemas</li><li>Missing protocol features: no support for resources, prompts, or sampling — only tools</li></ul><p><strong>Trade-off accepted:</strong> For a single-server, 3-tool use case, the SDK&#39;s overhead exceeds its value. The duplication risk is managed by keeping the MCP server&#39;s validation minimal (phase + terminal checks only) while the plugin&#39;s validation is authoritative.</p>',14)])])}const u=o(t,[["render",s]]);export{h as __pageData,u as default};
